import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.F7eQ-ohH.js";const o="/bzygq/assets/quesion_imgs_8fe398db0eae49e7b1f149c09c1791a1.BiriIYgV.png",r="/bzygq/assets/quesion_imgs_30fd203bae034a6e9542d7d3f49f5adb.5kXYvEyr.png",l="/bzygq/assets/quesion_imgs_26a7adbe8ae5444cbc9895a69455e47e.C52VDjNp.png",n="/bzygq/assets/quesion_imgs_f7c7beecabf24f3098311b17309695a3.DirPmzvm.png",_="/bzygq/assets/quesion_imgs_b47bac5fd9e54e3489717cda62519739.DqirhWf9.png",q=JSON.parse('{"title":"旋转、翻转定义","description":"","frontmatter":{},"headers":[],"relativePath":"行测/逻辑推理/1.图形推理/2. 旋转、翻转.md","filePath":"行测/逻辑推理/1.图形推理/2. 旋转、翻转.md","lastUpdated":1788883925000}'),p={name:"行测/逻辑推理/1.图形推理/2. 旋转、翻转.md"};function c(d,a,m,g,b,h){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="旋转、翻转定义" tabindex="-1">旋转、翻转定义 <a class="header-anchor" href="#旋转、翻转定义" aria-label="Permalink to &quot;旋转、翻转定义&quot;">​</a></h1><p>旋转、翻转是指图形绕某一固定中心点做圆周运动，仅改变位置，形状、大小保持不变，是行测图形推理中常考察的知识点，同时由于旋转和翻转比较容易观察到，解决这类问题相对也比较简单。</p><h2 id="旋转常见考点" tabindex="-1">旋转常见考点 <a class="header-anchor" href="#旋转常见考点" aria-label="Permalink to &quot;旋转常见考点&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><ol><li>方向：顺时针、逆时针</li><li>常见角度：45、60、90、120、180等肉眼可见的度数，不会旋转哪些难以分辨的角度。</li></ol><h2 id="翻转常见考点" tabindex="-1">翻转常见考点 <a class="header-anchor" href="#翻转常见考点" aria-label="Permalink to &quot;翻转常见考点&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><ol><li>左右翻转（垂直翻转）：两图沿竖轴对称</li><li>上下翻转（水平翻转）：两图沿横轴对称</li></ol><h1 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h1><ol><li><strong>请选择最合适的一项填入问号处，使之符合之前四个图形的变化规律：</strong></li></ol><p><img src="'+l+'" alt=""></p><p>解析：考查旋转固定角度；元素组成相同，位置变化。图形整体依次顺时针旋转135度，只有B符合此规律。故正确答案为B。</p><ol start="2"><li><strong>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：</strong></li></ol><p><img src="'+n+'" alt=""></p><p>解析：考查立体图形的旋转；两组图形优先观察第一组，均为同一个六面体，图1整体沿水平方向顺时针旋转90度得到图2，图2整体沿水平方向顺时针旋转90度得到图3。应用此规律，验证图1到图2，满足此规律，因此“？”处图形应由图2整体沿水平方向顺时针旋转90度得到，即顶面为田字面，左面为斜线面。故正确答案为B。</p><ol start="3"><li><strong>请从所给的四个选项中，选出最恰当的一项填入问号处，使之呈现一定的规律性。</strong></li></ol><p><img src="'+_+'" alt=""></p><p>解析：考查旋转和上下翻转；元素相同，位置不同，考虑位置变化；九宫格优先横向看，第一行中，图一逆时针旋转90度得到图二，图二上下翻转得到图三；第二行经验证，符合该规律；第三行应用规律，只有B项符合。故正确答案为B。</p>',18)])])}const u=e(p,[["render",c]]);export{q as __pageData,u as default};
